public class Main {
    public static void main(String[] args) {
        String pkg = "{p}";
        String dir = pkg.replace('.', '/');
        System.out.println("包名：" + pkg);
        System.out.println("目录：" + dir);
        System.out.println("产物落点：" + dir + "/{cls}.class");
        System.out.println("喊人的全名：" + pkg + ".{cls}");
    }
}
